// Auto-generated logo buffer (base64). Robust in client and SSR runtimes.
// Source: src/assets/Enercity_logo_FFF.png
const LOGO_BASE64 = '';

export function getLogoBuffer(): Uint8Array {
  const bin = atob(LOGO_BASE64);
  const bytes = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
  return bytes;
}
